True def transform(grid):
    bottom = max(r for r, row in enumerate(grid) if any(row))
    out = [[0 for _ in row] for row in grid]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            nc = c + r - bottom
            if v and 0 <= nc < len(row):
                out[r][nc] = v
    return out
